"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/data-table/variants/01-responsive";
import Variant1 from "./components/data-table/variants/02-default";
import Variant2 from "./components/data-table/variants/03-pagination";
const variants = { responsive: Variant0, default: Variant1, pagination: Variant2 };
export interface ArtemisDataTableProps {
  className?: string;
  variant?: "responsive" | "default" | "pagination";
}
export function ArtemisDataTable({ className, variant = "responsive" }: ArtemisDataTableProps) {
  const View = variants[variant];
  return (
    <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}>
      <View />
    </ArtemisScope>
  );
}
